def _canonicalize(value: Any) -> Any:
    """Recursively canonicalize a JSON-compatible value.

    Dict keys are sorted, tuples are converted to lists, and surrounding
    whitespace is stripped from strings. Numbers and booleans are preserved
    as-is, so no semantics are changed.
    """
    if isinstance(value, dict):
        return {key: _canonicalize(item) for key, item in sorted(value.items())}
    if isinstance(value, (list, tuple)):
        return [_canonicalize(item) for item in value]
    if isinstance(value, str):
        return value.strip()
    return value


class ToolCalls(Type):
    class ToolCall(BaseModel):
        name: str
        args: dict[str, Any]
        fingerprint: str = ""
        id: str = ""

        def __init__(self, **data: Any):
            super().__init__(**data)
            if not self.fingerprint:
                canonical = {"name": self.name, "args": _canonicalize(self.args)}
                canonical_str = json.dumps(canonical, sort_keys=True, separators=(",", ":"))
                digest = hashlib.sha256(canonical_str.encode("utf-8")).hexdigest()
                self.fingerprint = digest
                self.id = digest[:8]

    tool_calls: list[ToolCall]
